.back { margin-bottom: 22px; }
.task-form { margin-top: 22px; }
.task-list { display: grid; gap: 10px; margin-top: 16px; }
.task-row { display: flex; align-items: center; gap: 12px; padding: 14px 16px; background: white; border: 1px solid #e0e6ef; border-radius: 8px; }
.task-row input { flex: initial; }
.task-filter { margin-top: 18px; }
select { margin-left: 8px; padding: 8px; font: inherit; }

const tasksResponse = await fetch(`/api/projects/${match[1]}/tasks`);
const tasks = await tasksResponse.json();
app.innerHTML = `<button class="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1><form class="task-form"><label for="task-title">Task title</label><input id="task-title" type="text" aria-label="Task title"><button type="submit">Create task</button></form><p class="error" role="alert" aria-live="polite"></p><label class="task-filter" for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select><section class="task-list" aria-label="Tasks"></section>`;
app.querySelector('.back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
const list = app.querySelector('.task-list');
const filter = app.querySelector('#task-filter');
const drawTasks = () => {
  const shown = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === task.completed);
  list.innerHTML = shown.map(task => `<div class="task-row" data-testid="task-row"><input type="checkbox" aria-label="Complete ${escapeHtml(task.title)}" data-id="${task.id}" ${task.completed ? 'checked' : ''}><span>${escapeHtml(task.title)}</span></div>`).join('');
  list.querySelectorAll('input').forEach(box => box.addEventListener('change', async () => {
    const task = tasks.find(item => item.id === Number(box.dataset.id));
    task.completed = box.checked;
    await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: task.completed }) });
    drawTasks();
  }));
};
filter.addEventListener('change', drawTasks);
drawTasks();
app.querySelector('.task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const input = app.querySelector('#task-title');
  const title = input.value.trim();
  const error = app.querySelector('.error');
  if (!title) { error.textContent = 'Task title is required'; input.focus(); return; }
  const response = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
  if (response.ok) { tasks.push(await response.json()); input.value = ''; error.textContent = ''; drawTasks(); }
});
return;

